def eulerian_num(n, m):
    # Base case: if n is 0 or m is 0, return 0
    if n == 0 or m == 0:
        return 0

    # Initialize the result as 0 for base cases
    res = [0] * (m + 1)

    # Fill the result array using dynamic programming
    for i in range(1, n + 1):
        for j in range(1, min(i, m) + 1):
            res[j] += i * eulerian_num(i - 1, j - 1)

    return res[m]
```

