def lps(s):
    n = len(s)

    # Initialize the length of the longest prefix and suffix for each character
    lps = [0] * n

    # Find the longest palindromic subsequence recursively
    def expand_around_center(left, right):
        while left >= 0 and right < n and s[left] == s[right]:
            if right - left + 1 > lps[right]:
                lps[right] = left
            left -= 1
        return lps[right]

    # Call the recursive function for all characters in the string
    for i in range(n):
        lps[i] = expand_around_center(i, i)
    for i in range(n):
        lps[i] = expand_around_center(i, i)

    return lps[n-1]
```

