def swap_count(s):
    # Counting open brackets
    open_brackets = {'(', '['}

    # Dictionary to map closing brackets to their corresponding opening brackets
    close_to_open = {c: k for k, v in open_brackets.items() for c in v}

    # Stack to keep track of indices of opening brackets
    stack = []

    # Dictionary to store the balance of each substring
    balance = {}

    for i, char in enumerate(s):
        if char in close_to_open:
            if stack and stack[-1] != close_to_open[char]:
                return i - stack.pop()
            else:
                stack.append(i)
        else:
            if char == '(' or char == '[':
                stack.append(i)
            elif char == ')':
                if not stack:
                    return i
                j = stack.pop()
                balance[j] = i - j

    # If there's at least one unmatched closing bracket, return -1
    return len(balance) if any(b > 0 for b in balance.values()) else -1
```

