def is_majority_element(arr, n, k):
    # If there's more than one distinct element, return false
    if len(set(arr)) < 2:
        return False

    # Find the first occurrence of 'k'
    i = 0
    while i < n - 1:
        if arr[i] == arr[i + 1]:
            i += 1
        else:
            break

    # If such an element was found, check if it's not equal to any other element
    if i == 0 or (i > 0 and arr[i-1] != arr[i]):
        return False

    # If all elements were equal up to this point, check again for the middle element
    j = 0
    while j < i:
        if arr[j] == arr[i]:
            i += 1
        else:
            break

    # If we reached this point without finding a conflict, 'arr[i]' is a candidate for the majority element
    return i == k
```

