def modular_inverse(arr, p, n):
    # Calculate the greatest common divisor (GCD) of all elements in the array
    def gcd(a, b):
        while b:
            a, b = b, a % b

    g = gcd(gcd(p, n), p)

    # If GCD is not 1, it's impossible to find such x such that (x * p) % n == 1
    if g != 1:
        return -1

    # Find the modular inverse using Fermat's little theorem
    for i in range(n):
        if (i * g) % n == 1:
            return i
    return -1
```

