def is_subset_sum(nums, target_sum, current_sum):
    # If the current sum equals the target sum, return True
    if current_sum == target_sum:
        return True

    # If all elements have been used up or the current sum exceeds the target sum
    for i in range(len(nums)):
        if i != 0 and nums[i-1] == nums[i]:
            continue

        new_sum = current_sum + nums[i]

        # If the new sum is greater than the target sum, break the loop
        if new_sum > target_sum:
            break

        # Check if the new sum exists in the list
        if is_subset_sum(nums[i+1:], target_sum - new_sum, new_sum):
            return True

    return False
```

