def find_longest_repeating_subseq(s):
    # Dictionary to store the length of the longest repeating subsequence ending with each character
    dp = {}

    for i in range(len(s)):
        if s[i] in dp:
            dp[s[i]] += 1
        else:
            dp[s[i]] = 1

    max_length = 0

    # Iterate through all possible starting indices for the first substring
    for i in range(len(s)):
        current_length = 0

        # Iterate through all possible ending indices for the current substring
        for j in range(i+1, len(s)+1):
            substring = s[i:j]

            # If there's a repeated substring, update the maximum length found so far
            if substring in dp:
                current_length = max(current_length, dp[substring])

        # Update the result with the maximum length found
        if current_length > max_length:
            max_length = current_length

    return max_length
```

