    max_sum = float('-inf')

    # Iterate over all possible starting rows for the top row of the rectangle
    for i in range(r):
        j = 0
        while j < r:
            current_sum = 0

            # Iterate over all possible positions below the current row
            for k in range(j+1, r):
                if k != i:
                    current_sum += grid[i][k]

            # Update the maximum sum found so far
            max_sum = max(max_sum, current_sum)

            # If we've reached the bottom row, break the loop
            if j == r-1:
                break

    return max_sum
