def set_left_most_unset_bit(x):
    # Find the first unset bit starting from the least significant bit (rightmost)
    for i in range(32):
        if (x & (1 << i)) == 0:
            break
    else:
        raise ValueError("No unset bit found")

    # Set the leftmost unset bit to 1
    x |= (1 << (31 - i))

    return x
```

