def ncr_modp(n, r, m):
    # Calculate factorials using math.factorial
    from math import factorial

    def binom(n, k):
        return factorial(n) // (factorial(k) * factorial(n - k))

    # Compute binomial coefficient modulo m
    return binom(n, r) % m
