def count_Primes_nums(n):
    if n <= 1:
        return 0

    sieve = [True] * n
    s = 2
    while (s * s) < n:
        if (s in sieve):
            for i in range(s * s, n + 1, s):
                sieve[i - 2] = False
        s += 1

    return sieve.count(True)
```

