def solve(A, n):
    # Create dictionaries to count inversions for each element
    count_A = {}
    count_B = {}

    for i in range(n):
        if (A[i] in count_A):
            count_A[A[i]] += 1
        else:
            count_A[A[i]] = 1

        if (B[i] in count_B):
            count_B[B[i]] += 1
        else:
            count_B[B[i]] = 1

    # Calculate total inversions for A and B separately
    total_inversions_A = 0
    total_inversions_B = 0

    for key in count_A:
        total_inversions_A += min(count_A[key], count_B[key])

    for key in count_B:
        total_inversions_B += min(count_A[key], count_B[key])

    # Compare the number of inversions for both arrays
    return total_inversions_A == total_inversions_B
```

