def answer(a, b):
    # Calculate the least common multiple (LCM) using formula LCM(a, b) = |a*b| / GCD(a, b)
    def gcd(x, y):
        while(y):
            x, y = y, x % y

        return abs(x)

    # Calculate LCM using the formula
    lcm = (a * b) // gcd(a, b)

    # Check if the LCM lies within the given range [a, b]
    if lcm >= a and lcm <= b:
        return (a, b)
    else:
        return None
```

