    for i in range(len(triangle) - 1, -1, -1):
        # For each row, update the current element by adding the maximum value between the two preceding elements
        for j in range(len(triangle[i])):
            if j > 0:
                triangle[i][j] += max(triangle[i-1][j-1], triangle[i-1][j])
    # Return the maximum value found in the last row of the triangle
    return max(triangle[-1])
