def find_rotation_count(arr):
    n = len(arr)

    # If the array has one or no elements, there's no rotation needed
    if n == 1:
        return 0

    # Find the index of the first occurrence of 'arr[n-1]'
    i = 0
    while i < n - 1:
        if arr[i] == arr[i + 1]:
            i += 1
        else:
            break
    else:
        return 0

    # Find the second occurrence of 'arr[n-1]' by adjusting the search range
    j = n - 1
    while j >= i:
        if arr[j] == arr[i]:
            return j - i + 1
        j -= 1

    return 0
```

