def max_sub_array_sum_repeated(nums, k, n):
    # If k is greater than or equal to the length of the array, all elements form a subarray
    if k >= len(nums):
        return max(nums)

    # Initialize variables
    current_sum = total_sum = max_sum = 0

    # Iterate through all possible ways to form a subarray of size k
    for i in range(n):
        for j in range(i+1, n+k):
            subarray = nums[i:j+1]

            # If the subarray forms a valid subarray of size k, update the results
            if len(subarray) == k:
                current_sum += max(subarray)

                # Update the maximum sum found so far
                max_sum = max(max_sum, current_sum)

                # Reset the current sum for the next iteration
                current_sum = 0

    return max_sum
```

