def next_smallest_palindrome(num):
    # Convert the number to a string
    num_str = str(num)

    # Find the longest consecutive repeated digit
    for i in range(len(num_str)):
        if len(set(num_str[i:])) == 1 and int(num_str[i]) > int(num_str[i-1]):
            break

    # If such a pair is found, remove it from the string
    if i == len(num_str) - 1:
        return int(num_str[:i+1])

    # Otherwise, add one more character after the last occurrence of this digit
    return int(num_str + (int(num_str[-1]) + 1))
