def max_path_sum(triangle):
    n = len(triangle)

    for i in range(n - 2, -1, -1):
        for j in range(i + 1):
            if j == 0:
                triangle[i][j] += max(triangle[i + 1][0], triangle[i + 1][j])
            elif j == i:
                triangle[i][j] += max(triangle[i - 1][j - 1], triangle[i - 1][j])
            else:
                triangle[i][j] += max(triangle[i - 1][j], triangle[i - 1][j + 1])

    return triangle[0][0]
```

