def sort_on_occurence(lst):
    # Create a dictionary to count occurrences of the first element of each tuple
    counts = {}
    for item in lst:
        if item[0] in counts:
            counts[item[0]] += 1
        else:
            counts[item[0]] = 1

    # Sort the items based on their values in descending order, then by index in ascending order
    sorted_items = sorted(counts.items(), key=lambda x: (-x[1], x[0]), reverse=True)

    # Extract the first element of each sorted tuple
    sorted_results = [item[0] for item in sorted_items]

    return sorted_results
