def max_product(nums, n):
    # If there's only one element, return its value as it's the maximum product of single elements
    if n == 1:
        return max(nums)

    # Initialize variables
    max_product = nums[0]
    current_max = nums[0]

    # Iterate through all possible subsequences of length n-1
    for i in range(1, len(nums), 1):
        # Update current_max if the product of current_max and nums[i] is positive
        if (current_max * nums[i]) > 0:
            current_max *= nums[i]
        else:
            current_max = nums[i]

        # Update max_product if the current_max is greater than max_product
        max_product = max(max_product, current_max)

    return max_product
```

