def magic_square(matrix):
    n = len(matrix)

    # Check if the matrix is a square
    for row in matrix:
        if len(row) != n:
            return False

    # Initialize the first row as the middle element of the first row
    first_row = matrix[0]

    # Fill the rest of the matrix by placing numbers from 1 to n^2 in order
    for i in range(n):
        matrix[i] = [j + (i - 1) * (n // 2) + 1 for j in first_row]

    return all(x == y for x, y in zip(matrix[0], matrix[1])) and all(x == y for x, y in zip(matrix[1], matrix[2])))
```

