def get_total_number_of_sequences(n, m):
    # Initialize a list where each index represents a possible value up to m
    dp = [0] * (m + 1)

    # Iterate over all possible starting values for the first element of the sequence
    for i in range(m + 1):
        # Check if the current value can form a valid sequence
        for j in range(i, -1, -1):
            if j >= 2 * i and j <= m:
                dp[i] += dp[j - 2]

    return dp[n]
