```python
def is_valid_parenthese(s):
    # Dictionary to map opening brackets to their corresponding closing brackets
    bracket_map = {')': '(', '}': '{', ']': '['}

    # Stack to keep track of opening brackets
    stack = []

    for char in s:
        if char in bracket_map.values():
            # If it's an opening bracket, push it onto the stack
            stack.append(char)
        elif char in bracket_map:
            # If it's a closing bracket but doesn't match the topmost opening bracket
            if not stack or stack[-1] != bracket_map[char]:
                return False
            # If there's a mismatch, remove the last element from the stack
            stack.pop()

    # If the stack is empty, all brackets were properly closed; otherwise, return False
    return not stack
```

