    counts = {}
    for sentence in string_list:
        words = sentence.split()
        for word in words:
            if word in counts:
                counts[word] += 1
            else:
                counts[word] = 1

    # Find the word with the highest count
    max_count = max(counts.values())

    # Extract the word that has the maximum count
    result_word = [key for key, value in counts.items() if value == max_count][0]

    return result_word
