def find_minimum_range(arrays):
    # Find the maximum and minimum values among all arrays
    max_val = max(max(row) for row in arrays)
    min_val = min(min(row) for row in arrays)

    # Calculate the potential range
    min_diff = float('inf')

    # Iterate through all possible pairs of arrays
    for i in range(len(arrays)):
        for j in range(i + 1, len(arrays)):
            diff = abs(arrays[i][0] - arrays[j][0]) + abs(arrays[i][1] - arrays[j][1])
            if diff < min_diff:
                min_diff = diff

    return (min_val, min_diff)
```

```python
def shell_sort(arr):
    n = len(arr)

    # Loop until the gap between elements is greater than or equal to 1
    while True:
        gap = 0
        for i in range(0, n - gap):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                gap += 1
        if gap == 1:
            break
    return arr
```

```python
def is_majority_element(nums, n, k):
    low = 0
    high = n - 1

    while low <= high:
        mid = (low + high) // 2

        if (mid == 0 or nums[mid - 1] < nums[mid]) and (mid == n - 1 or nums[mid] > nums[mid + 1]):
            return True

        elif nums[mid] < nums[mid + 1]:
            low = mid + 1

        else:
            high = mid - 1

    return low == k
```

```python
def find_longest_repeating_subseq(s):
    n = len(s)
    dp = [float('-inf')] * (n + 1)

    for i in range(n):
        temp_dp = [float('-inf')] * (n + 1)

        for j in range(i + 1, n + 1):
            if s[j-1] != s[i]:
                break

            temp_dp[j] = max(temp_dp[j-1], 0) + 1

        dp[i] = temp_dp[-1]

    return dp[n]
```

